-- Transactional business events; no remote telemetry or cross-service foreign keys.
CREATE TABLE evidence.event_outbox(event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE,event_type text NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,aggregate_version text NOT NULL,payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),correlation_id text NOT NULL);
CREATE TABLE evidence.event_outbox_delivery(event_id uuid NOT NULL REFERENCES evidence.event_outbox ON DELETE CASCADE,target text NOT NULL CHECK(target IN ('identidad','aprendizaje','comunidad','evidencias')),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','retry','delivered','deadletter')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token uuid,delivered_at timestamptz,last_error text,PRIMARY KEY(event_id,target));
CREATE INDEX event_delivery_due_idx ON evidence.event_outbox_delivery(available_at,event_id) WHERE status IN ('pending','retry','processing');
CREATE TABLE evidence.event_inbox(source text NOT NULL,event_id uuid NOT NULL,source_sequence bigint NOT NULL,event_type text NOT NULL,request_hash char(64) NOT NULL,correlation_id text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,PRIMARY KEY(source,event_id));
CREATE TABLE evidence.event_projection(source text NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,source_sequence bigint NOT NULL,aggregate_version text NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz NOT NULL,correlation_id text NOT NULL,PRIMARY KEY(source,aggregate_type,aggregate_id));
CREATE FUNCTION evidence.emit_domain_event(event_type text,aggregate_type text,aggregate_id uuid,aggregate_version text,payload jsonb) RETURNS void LANGUAGE plpgsql AS $$ DECLARE event_uuid uuid; BEGIN
 INSERT INTO evidence.event_outbox(event_type,aggregate_type,aggregate_id,aggregate_version,payload,correlation_id) VALUES(event_type,aggregate_type,aggregate_id,aggregate_version,payload,COALESCE(NULLIF(current_setting('app.correlation_id',true),''),gen_random_uuid()::text)) RETURNING event_id INTO event_uuid;
 INSERT INTO evidence.event_outbox_delivery(event_id,target) SELECT event_uuid,target FROM unnest(ARRAY['identidad','aprendizaje','comunidad']) target;
END $$;
CREATE FUNCTION evidence.report_business_event() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM evidence.emit_domain_event(CASE WHEN TG_OP='INSERT' THEN 'report.created' ELSE 'report.changed' END,'report',NEW.informe_id,COALESCE(to_jsonb(NEW)->>'snapshot_version','0'),jsonb_build_object('reportId',NEW.informe_id,'workspaceId',NEW.espacio_id,'accountId',NEW.solicitado_por,'state',COALESCE(to_jsonb(NEW)->>'generation_status','pending'))); RETURN NEW; END $$;
CREATE TRIGGER report_business_event AFTER INSERT OR UPDATE ON evidence.informe FOR EACH ROW EXECUTE FUNCTION evidence.report_business_event();
GRANT SELECT,INSERT,UPDATE,DELETE ON evidence.event_outbox,evidence.event_outbox_delivery,evidence.event_inbox,evidence.event_projection TO evidence_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA evidence TO evidence_app;
